def _is_nvidia_hopper() -> bool:
    if not is_nvidia:
        return False
    if not torch.cuda.is_initialized():
        from vllm.platforms.cuda import NvmlCudaPlatform

        if isinstance(current_platform, NvmlCudaPlatform):
            # Torch's device-name argument is a visible ordinal, which may
            # differ from a vLLM logical ID when GPUs have been assigned.
            physical_id = current_platform.visible_device_id_to_physical_device_id(0)
            name = current_platform._get_physical_device_name(physical_id)
            if "NVIDIA H" in name:
                return True
            capability = current_platform.get_device_capability(0)
            if capability is not None:
                return capability.major >= 9
    # Keep the original visible-name/current-capability selection after
    # initialization and for native non-NVML fallback. The latter may
    # initialize CUDA; vLLM's multiprocessing safety guard remains active.
    return (
        "NVIDIA H" in torch.cuda.get_device_name(0)
        or torch.cuda.get_device_capability()[0] >= 9
    )


is_nvidia_hopper = _is_nvidia_hopper()
